type SwsecCounters struct {
	// Number of packets dropped by BPDU Filtering. When the BPDU Filter is enabled, traffic to the configured BPDU destination MAC addresses format: int64
	BpduFilterDrops *int64
	// Number of IPv4 DHCP packets dropped by DHCP Client Block. DHCP Client Block prevents a VM from acquiring DHCP IP address by blocking DHCP requests format: int64
	DhcpClientBlockIpv4Drops *int64
	// Number of DHCPv6 packets dropped by DHCP Client Block. DHCP Client Block prevents a VM from acquiring DHCP IP address by blocking DHCP requests format: int64
	DhcpClientBlockIpv6Drops *int64
	// Number of IPv4 DHCP packets dropped because addresses in the payload were not valid format: int64
	DhcpClientValidateIpv4Drops *int64
	// Number of IPv4 DHCP packets dropped by DHCP Server Block. DHCP Server Block blocks traffic from a DHCP Server to a DHCP Client format: int64
	DhcpServerBlockIpv4Drops *int64
	// Number of DHCPv6 packets dropped by DHCP Server Block. DHCP Server Block blocks traffic from a DHCP Server to a DHCP Client format: int64
	DhcpServerBlockIpv6Drops *int64
	// Number of IPv 6 Router Advertisement packets dropped by RA Guard. format: int64
	NdParseErrors *int64
	// Number of IPv6 Neighbor Discovery (ND) packets which were not correctly parsed format: int64
	RaGuardDrops *int64
	// Number of transmitted IPv6 packets format: int64
	RxArpPkts *int64
	// Number of transmitted ARP packets format: int64
	RxGarpPkts *int64
	// Number of received IPv4 packets format: int64
	RxIpv4Pkts *int64
	// Number of received IPv6 packets format: int64
	RxIpv6Pkts *int64
	// Number of IPv6 ND (Neighbor Discovery) NA (Neighbor Advertisement) packets format: int64
	RxNaPkts *int64
	// Number of transmitted Gratuitous ARP (GARP) packets format: int64
	RxNonIpPkts *int64
	// Number of IPv6 ND (Neighbor Discovery) NS (Neighbor Solicitation) packets format: int64
	RxNsPkts *int64
	// Number of ingress packets dropped by broadcast Rate Limiting format: int64
	RxRateLimitBcastDrops *int64
	// Number of ingress packets dropped by multicast Rate Limiting format: int64
	RxRateLimitMcastDrops *int64
	// Number of IPv6 ND (Neighbor Discovery) NA (Neighbor Advertisement) packets which, were unsolicited format: int64
	RxUnsolicitedNaPkts *int64
	// Number of IPv6 packets dropped by Spoof Guard. SpoofGuard protects against IP spoofing by maintaining a reference table of , VM names and IP addresses format: int64
	SpoofGuardArpDrops *int64
	// Number of IPv4 packets dropped by Spoof Guard. SpoofGuard protects against IP spoofing by maintaining a reference table of , VM names and IP addresses format: int64
	SpoofGuardIpv4Drops *int64
	// Number of IPv6 Neighbor Discovery (ND) packets dropped by Spoof Guard. SpoofGuard protects against ND Spoofing by filtering out ND packets whose addresses, do not match the VM's address format: int64
	SpoofGuardIpv6Drops *int64
	// Number of ARP packets dropped by Spoof Guard. Spoof Guard protects against malicious ARP spoofing attacks by keeping track of , MAC and IP addresses format: int64
	SpoofGuardNdDrops *int64
	// Number of Non-IP packets dropped by Spoof Guard format: int64
	SpoofGuardNonIpDrops *int64
	// Number of received ARP packets format: int64
	TxArpPkts *int64
	// Number of transmitted IPv4 packets format: int64
	TxIpv4Pkts *int64
	// Number of received non-IP packets format: int64
	TxIpv6Pkts *int64
	// Number of transmitted non-IP packets format: int64
	TxNonIpPkts *int64
	// Number of egress packets dropped by broadcast Rate Limiting format: int64
	TxRateLimitBcastDrops *int64
	// Number of egress packets dropped by multicast Rate Limiting format: int64
	TxRateLimitMcastDrops *int64
}

